-- Tanda formato 3 (revisión 2026-10): 31 explicaciones que no descartaban todas las opciones -> texto nuevo y 'revisada'.
-- Guarda md5 por fila sobre el texto anterior; si no cuadran 31 actualizadas = 31 en el historial, ROLLBACK de todo.
BEGIN;
CREATE TEMP TABLE tc (id int, antes_md5 text, despues text) ON COMMIT DROP;
CREATE TEMP TABLE h0 ON COMMIT DROP AS SELECT count(*) n FROM explicaciones_historial;
SET LOCAL mir.motivo = 'Tanda formato 3 2026-10';
DO $$ DECLARE n int; h int; BEGIN
  WITH u AS (UPDATE preguntas p SET explicacion = tc.despues, explicacion_calidad = 'revisada'
    FROM tc WHERE p.id = tc.id AND md5(p.explicacion) = tc.antes_md5 AND p.explicacion_calidad <> 'controversia' RETURNING 1)
  SELECT count(*) INTO n FROM u;
  SELECT (SELECT count(*) FROM explicaciones_historial) - h0.n INTO h FROM h0;
  IF n <> 31 OR h <> 31 THEN RAISE EXCEPTION 'actualizadas %, historial +% (esperado 31): ROLLBACK de todo', n, h; END IF;
  RAISE NOTICE 'actualizadas %, historial +%', n, h;
END $$;
COMMIT;
